use std::{env,fs,process::Command,thread,time::{Duration,Instant}};
fn number(path:&str)->u64{fs::read_to_string(path).unwrap().trim().parse().unwrap()}
fn cpu()->(u64,u64,u64){let s=fs::read_to_string("/sys/fs/cgroup/cpu.stat").unwrap();let get=|k:&str|s.lines().find_map(|l|{let mut p=l.split_whitespace();if p.next()==Some(k){p.next()?.parse().ok()}else{None}}).unwrap_or(0);(get("usage_usec"),get("nr_throttled"),get("throttled_usec"))}
fn main(){let a:Vec<String>=env::args().skip(1).collect();let before=cpu();let start=Instant::now();let mut child=Command::new(&a[0]).args(&a[1..]).spawn().unwrap();let pid=child.id();let mut last=before.0;let mut last_time=Instant::now();let mut peak_cpu=0f64;let mut peak_threads=0u64;let mut peak_rss=0u64;let mut peak_mem=0u64;let mut polls=0u64;
let status=loop{thread::sleep(Duration::from_millis(100));let now=Instant::now();let current=cpu().0;let pc=(current-last) as f64/(now-last_time).as_secs_f64()/10000.;peak_cpu=peak_cpu.max(pc);last=current;last_time=now;
if let Ok(s)=fs::read_to_string(format!("/proc/{pid}/status")){for l in s.lines(){let mut parts=l.split_whitespace();match parts.next(){Some("Threads:")=>peak_threads=peak_threads.max(parts.next().unwrap().parse().unwrap()),Some("VmRSS:")=>peak_rss=peak_rss.max(parts.next().unwrap().parse().unwrap()),_=>{}}}}
peak_mem=peak_mem.max(number("/sys/fs/cgroup/memory.current"));polls+=1;if let Some(s)=child.try_wait().unwrap(){break s}};
let elapsed=start.elapsed().as_secs_f64();let after=cpu();let memory_peak=number("/sys/fs/cgroup/memory.peak");
eprintln!("RESOURCE {{\"wall_seconds\":{},\"cpu_seconds\":{},\"cpu_average_percent\":{},\"cpu_peak_100ms_percent\":{},\"peak_process_threads_sampled\":{},\"peak_process_rss_kib_sampled\":{},\"peak_container_memory_bytes\":{},\"peak_container_memory_bytes_sampled\":{},\"cpu_throttled_periods\":{},\"cpu_throttled_seconds\":{},\"samples\":{},\"exit_code\":{}}}",elapsed,(after.0-before.0) as f64/1e6,(after.0-before.0) as f64/elapsed/10000.,peak_cpu,peak_threads,peak_rss,memory_peak,peak_mem,after.1-before.1,(after.2-before.2) as f64/1e6,polls,status.code().unwrap_or(-1));
std::process::exit(status.code().unwrap_or(1));}
